var datum, txt, StromZoe;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - priority.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");
}


// Datenpunkte
createState("javascript.0.Priorität.Prio_maxZoe", 0, JSON.parse('{"name": "Prio_maxZoe","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 6,"max": 32,"def": 0,"read": true,"write": true}'), async function () {
});
createState("javascript.0.Priorität.Prio_maxTesla", 0, JSON.parse('{"name": "Prio_maxTesla","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 6,"max": 16,"def": 0,"read": true,"write": true}'), async function () {
});
createState("javascript.0.Priorität.Prio_aktStromproPhase_Zoe", 0, JSON.parse('{"name": "Prio_aktStromproPhase_Zoe","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 0,"max": 40,"def": 0,"read": true,"write": true}'), async function () {
});
createState("javascript.0.Priorität.Prio_aktStromproPhase_Tesla", 0, JSON.parse('{"name": "Prio_aktStromproPhase_Tesla","role": "","type": "number","desc": "Blockly erzeugt","unit": "","min": 0,"max": 40,"def": 0,"read": true,"write": true}'), async function () {
});
// Strom pro Phase
schedule("* * * * * *", async function () {
  setState("javascript.0.Priorität.Prio_aktStromproPhase_Zoe"/*Prio_aktStromproPhase_Zoe*/, 0);
  setState("javascript.0.Priorität.Prio_aktStromproPhase_Tesla"/*Prio_aktStromproPhase_Tesla*/, 0);
  // Zoe
  if (getState("go-e.1.allow_charging").val) {
    setState("javascript.0.Priorität.Prio_aktStromproPhase_Zoe"/*Prio_aktStromproPhase_Zoe*/, getState("go-e.1.energy.phase1.ampere").val);
  }
  // Tesla
  if (getState("go-e.0.allow_charging").val) {
    setState("javascript.0.Priorität.Prio_aktStromproPhase_Tesla"/*Prio_aktStromproPhase_Tesla*/, getState("go-e.0.energy.phase1.ampere").val);
  }
});
// LOG
on({id: "javascript.0.Priorität.Prio_aktStromproPhase_Zoe"/*Prio_aktStromproPhase_Zoe*/, change: "ne"}, async function (obj) {
  var value = obj.state.val;
  var oldValue = obj.oldState.val;
  if (getState("javascript.0.Zoe.DebugAktiv").val) {
    await Logfile(formatDate(new Date(), "YYYY.MM.DD"), 'akt. Strom pro Phase - Zoe (A): ' + String(getState("javascript.0.Priorität.Prio_aktStromproPhase_Zoe").val));
  }
});
on({id: "javascript.0.Priorität.Prio_aktStromproPhase_Tesla"/*Prio_aktStromproPhase_Tesla*/, change: "ne"}, async function (obj) {
  var value = obj.state.val;
  var oldValue = obj.oldState.val;
  if (getState("javascript.0.Zoe.DebugAktiv").val) {
    await Logfile(formatDate(new Date(), "YYYY.MM.DD"), 'akt. Strom pro Phase - Tesla (A): ' + String(getState("javascript.0.Priorität.Prio_aktStromproPhase_Tesla").val));
  }
});
// -------Priority Management-------
on({id: [].concat(['javascript.0.Priorität.Prio_aktStromproPhase_Zoe']).concat(['javascript.0.Priorität.Prio_aktStromproPhase_Tesla']), change: "ne"}, async function (obj) {
    if (getState("javascript.0.Zoe.DebugAktiv").val) {
    await Logfile(formatDate(new Date(), "YYYY.MM.DD"), '----- Prio Control --- START ');
  }
  StromZoe = 40;
  setState("javascript.0.Priorität.Prio_maxTesla"/*Prio_maxTesla*/, 16);
  setState("javascript.0.Priorität.Prio_maxZoe"/*Prio_maxZoe*/, 32);
  // Pool
  if (getState("s7.0.Outputs.0.Q1").val) {
    StromZoe = parseFloat(StromZoe) - 2;
    await Logfile(formatDate(new Date(), "YYYY.MM.DD"), 'Pool Pumpe - StromZoe (A): ' + String(StromZoe));
  }
  if (getState("s7.0.Outputs.0.Q4").val) {
    StromZoe = parseFloat(StromZoe) - 16;
    await Logfile(formatDate(new Date(), "YYYY.MM.DD"), 'Pool Heizung - StromZoe (A): ' + String(StromZoe));
  }
  // Tesla
  if (getState("go-e.0.energy.power").val != 0 && getState("0_userdata.0.go-e.3P").val) {
    StromZoe = parseFloat(StromZoe) - getState("go-e.0.amperePV").val;
    await Logfile(formatDate(new Date(), "YYYY.MM.DD"), 'Tesla - StromZoe (A): ' + String(StromZoe));
  }
  // Begrenzung ZOE
  setState("javascript.0.Priorität.Prio_maxZoe"/*Prio_maxZoe*/, (Math.min(Math.max(StromZoe, 6), 32)));
  await Logfile(formatDate(new Date(), "YYYY.MM.DD"), '----- Prio Control --- END ');
});

// LOG ----------------------
on({id: "javascript.0.Priorität.Prio_aktStromproPhase", change: "ne"}, async function (obj) {
  var value = obj.state.val;
  var oldValue = obj.oldState.val;
  await Logfile(formatDate(new Date(), "YYYY.MM.DD"), 'PRIO / Strom pro Phase (A): ' + String(('' + (obj.state ? obj.state.val : ""))));
});
on({id: "javascript.0.Priorität.Prio_maxTesla"/*Prio_maxTesla*/, change: "ne"}, async function (obj) {
  var value = obj.state.val;
  var oldValue = obj.oldState.val;
  await Logfile(formatDate(new Date(), "YYYY.MM.DD"), 'PRIO / max Tesla (A): ' + String(('' + (obj.state ? obj.state.val : ""))));
});
on({id: "javascript.0.Priorität.Prio_aktStromproPhase", change: "ne"}, async function (obj) {
  var value = obj.state.val;
  var oldValue = obj.oldState.val;
  await Logfile(formatDate(new Date(), "YYYY.MM.DD"), 'PRIO / max Zoe (A): ' + String(('' + (obj.state ? obj.state.val : ""))));
});


